{
  "findings": [
    {
      "title": "HECSI maximum score calculation inconsistent with scoring rules",
      "page": 73,
      "quote": "the score given for the extent at each location is multiplied by the total sum of the intensity of each clinical feature, and the total sum called the HECSI score is calculated, varying from 0 to a maximum severity score of 360 points.",
      "severity": "major"
    },
    {
      "title": "HECSI assessment timing contradictory statements",
      "page": 74,
      "quote": "This assessment will be performed at time points according Section 9.1 . The HECSI is provided in the study reference manual. The HECSI will be assessed at time points according to Table 1.",
      "severity": "minor"
    },
    {
      "title": "WPAI+CIQ acronym typo (WAPI instead of WPAI)",
      "page": 75,
      "quote": "the patients will answer the applicable questions in WAPI components or CIQ components or both.",
      "severity": "minor"
    },
    {
      "title": "Cross-reference to non-existent Section 9.1",
      "page": 73,
      "quote": "This assessment will be performed at time points according to Section 9.1 .",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 5",
      "page": 84,
      "quote": "Analysis variables are listed in Section 5.",
      "severity": "major"
    },
    {
      "title": "Cross-reference to non-existent Section 4",
      "page": 84,
      "quote": "Endpoints are listed in Section 4",
      "severity": "major"
    },
    {
      "title": "Inconsistent AE follow-up duration",
      "page": 79,
      "quote": "AEs should be followed until they are resolved or last study visit, whichever comes first.",
      "severity": "minor"
    },
    {
      "title": "Injection site reaction severity scale has overlapping ranges",
      "page": 82,
      "quote": "5.1 cm to 10 cm erythema or induration or induration that interferes with activity",
      "severity": "minor"
    },
    {
      "title": "Missing definition of 'success rate' in statistical hypothesis",
      "page": 84,
      "quote": "the success rate (where success is proportion of patients achieving an IGA score of 0 or 1 on hand and foot at week 16) is equal between dupilumab and placebo",
      "severity": "minor"
    },
    {
      "title": "Inconsistent use of 'blinded' vs 'unblinded' in safety reporting",
      "page": 84,
      "quote": "All notifications to investigators will contain only blinded information.",
      "severity": "minor"
    }
  ]
}
